import {fixedUsdPrice} from './stablecoins.mjs';
const priceChains={'1':'ethereum','56':'bsc','8453':'base','137':'polygon','10':'optimism','42161':'arbitrum','59144':'linea','57073':'ink','196':'xlayer',solana:'solana'};
const nativeIds={'1':'ethereum','4663':'ethereum','8453':'ethereum','10':'ethereum','42161':'ethereum','59144':'ethereum','57073':'ethereum','56':'binancecoin','137':'polygon-ecosystem-token','196':'okb','5042':'usd-coin',solana:'solana'};
export async function lookupPrices(assets,fetcher=fetch){
 const prices={},errors=[];for(const a of assets){const p=fixedUsdPrice(a.chain,a.asset);if(p)prices[a.chain+':'+a.asset]=p}assets=assets.filter(a=>!fixedUsdPrice(a.chain,a.asset));const get=async url=>{const r=await fetcher(url,{redirect:'manual',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('报价接口 HTTP '+r.status);return r.json()};
 if(assets.some(a=>a.asset==='native'))try{const ids=[...new Set(assets.filter(a=>a.asset==='native'&&nativeIds[a.chain]).map(a=>nativeIds[a.chain]))];const result=await get('https://api.coingecko.com/api/v3/simple/price?ids='+ids.join(',')+'&vs_currencies=usd&include_last_updated_at=true');for(const a of assets.filter(a=>a.asset==='native')){const q=result[nativeIds[a.chain]];if(q?.usd>0&&q.last_updated_at&&Date.now()-q.last_updated_at*1000<15*60e3)prices[a.chain+':native']={usd:String(q.usd),at:q.last_updated_at*1000,source:'CoinGecko'}}}catch(e){errors.push('原生币报价暂不可用');errors.push('主报价源: '+String(e.message).slice(0,100))}
 // Token identity is chain + exact contract, never the displayed ticker.
 for(const chain of [...new Set(assets.filter(a=>a.asset!=='native').map(a=>a.chain))]){if(!priceChains[chain])continue;try{const wanted=assets.filter(a=>a.chain===chain&&a.asset!=='native');const pairs=await get('https://api.dexscreener.com/tokens/v1/'+priceChains[chain]+'/'+wanted.map(a=>a.asset).join(','));if(!Array.isArray(pairs))throw Error();for(const a of wanted){const eq=x=>chain==='solana'?x===a.asset:x?.toLowerCase()===a.asset.toLowerCase();const best=pairs.filter(q=>q.chainId===priceChains[chain]&&eq(q.baseToken?.address)&&Number(q.priceUsd)>0&&q.liquidity?.usd>=10000).sort((a,b)=>b.liquidity.usd-a.liquidity.usd)[0];if(best)prices[chain+':'+a.asset]={usd:best.priceUsd,at:Date.now(),source:'DEX Screener'}}}catch(e){errors.push(chain+' 代币报价暂不可用: '+String(e.message).slice(0,100))}}
 // Public wrapped-native markets provide a fallback when CoinGecko limits hosting IPs.
 const nativeMarkets={ethereum:['ethereum','0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2'],solana:['solana','So11111111111111111111111111111111111111112'],binancecoin:['bsc','0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c'],'polygon-ecosystem-token':['polygon','0x0d500B1d8E8eF31E21C99d1Db9A6444d3ADf1270'],okb:['ethereum','0x75231F58b43240C9718Dd58B4967c5114342a86c'],'usd-coin':['ethereum','0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48']};
 await Promise.all([...new Set(assets.filter(a=>a.asset==='native'&&!prices[a.chain+':native']).map(a=>nativeIds[a.chain]).filter(Boolean))].map(async id=>{try{const [chain,contract]=nativeMarkets[id],pairs=await get('https://api.dexscreener.com/tokens/v1/'+chain+'/'+contract);const best=pairs.filter(p=>p.chainId===chain&&(chain==='solana'?p.baseToken?.address===contract:p.baseToken?.address?.toLowerCase()===contract.toLowerCase())&&Number(p.priceUsd)>0&&p.liquidity?.usd>=10000).sort((a,b)=>b.liquidity.usd-a.liquidity.usd)[0];if(best)for(const a of assets)if(a.asset==='native'&&nativeIds[a.chain]===id&&!prices[a.chain+':native'])prices[a.chain+':native']={usd:best.priceUsd,at:Date.now(),source:'DEX Screener（原生币对应市场）'}}catch(e){errors.push(id+' 备用报价: '+String(e.message).slice(0,100))}}));
 return {prices,errors:errors.filter(e=>!e.startsWith('主报价源:')&&(e!=='原生币报价暂不可用'||assets.some(a=>a.asset==='native'&&nativeIds[a.chain]&&!prices[a.chain+':native'])))};
}
